window.RTR_T=window.RTR_T||{};RTR_T["n1"]={"code": "N-1", "title": "Oftalmologiyaning rivojlaniş tarixi. Köruv organi anatomiyasi. Közning köriş faoliyati", "hours": 2, "minutes": 80, "goal": "Öquvçilarda oftalmologiya fanining mazmuni, qisqaça rivojlaniş tarixi, köruv organining anatomik tuzilişi va közning asosiy köriş funksiyalari töğrisida bilim hamda ularni hamşiralik amaliyotida qöllaş könikmalarini şakllantiriş.", "plan": ["“Oftalmologiya” fani haqida tuşunça va uning tibbiyot fanlari orasidagi örni", "Oftalmologiya fanining rivojlaniş tarixi", "Köruv organi anatomiyasi", "Köruv organining faoliyati (köriş funksiyalari)"], "outcomes": ["Oftalmologiya fani haqida tuşunça va uning tibbiyot fanlari orasidagi örnini aytib beradi.", "Oftalmologiya fanining qisqaça rivojlaniş tarixini, unga hissa qöşgan olimlarni sanab beradi.", "Közning tuzilişi, pardalari, içki muhitlari va yordamçi apparatini aytib, rasmda körsatib beradi.", "Közning köriş faoliyati: markaziy, periferik, rang, yoruğlik va binokulyar körişni tuşuntirib beradi."], "keywords": ["oftalmologiya", "köruv analizatori", "köz olmasi", "şox parda", "sklera", "tomirli parda", "tör parda", "gavhar", "şişasimon tana", "köriş ötkirligi", "köruv maydoni", "rang köriş", "binokulyar köriş"], "methods": [{"name": "Tezkor savol-javob (blits-sörov)", "stage": "Tayanç bilimlarni faollaştiriş (5 daqiqa)", "goal": "Anatomiya va fiziologiya fanlaridan olingan bilimlarni yodga tuşiriş, yangi mavzuga köprik yaratiş.", "steps": ["Öqituvçi qisqa, aniq javob talab qiladigan savollarni ketma-ket beradi.", "Öquvçilar navbat bilan 10–15 soniyada javob beradi.", "Notöğri javoblar darhol boşqa öquvçi tomonidan töğrilanadi."], "task": ["“Oftalmos” sözi nimani anglatadi?", "Analizator neça qismdan iborat?", "Köruv organining asosiy va yordamçi qismlarini ayting.", "Köruv markazi boş miyaning qaysi bölagida joylaşgan?"]}, {"name": "Taqdimot va vizual körgazmali bayon (mini-maʼruza)", "stage": "Yangi materialni bayon qiliş (35 daqiqa)", "goal": "Mavzuning nazariy holatlarini slaydlar, infografika va animatsiya yordamida tuşunarli yetkaziş.", "steps": ["Reja asosida har bir savol slaydlar orqali şarhlanadi.", "Köz olmasi kesimi rasmida har bir parda va muhit körsatgiç bilan körsatiladi.", "“Nur yöli” animatsiyasi orqali köriş jarayoni namoyiş etiladi.", "Öquvçilar asosiy tuşunçalarni daftarga yozib boradi."], "task": ["Slaydlar: RTR → “Taqdimot” bölimi", "Animatsiya: RTR → “Media” bölimi"]}, {"name": "Klaster (tarmoqlaş)", "stage": "Yangi materialni tizimlaştiriş (7 daqiqa)", "goal": "Köruv organining tuzilmalari örtasidagi boğliqlikni grafik körinişda ifodalaş.", "steps": ["Doska markaziga “KÖRUV ORGANI” sözi yoziladi.", "Öquvçilar undan tarmoqlar çiqaradi: köz olmasi → pardalar → qismlari; içki muhitlar; yordamçi apparat.", "Har bir tarmoq oxiriga tuzilmaning vazifasi yoziladi.", "Tayyor klaster maʼruzadagi jadval bilan soliştiriladi."], "task": ["Köz olmasining uç pardasi va ularning qismlari böyiça klaster tuzing."]}, {"name": "“Galereya böylab sayohat”", "stage": "Mustahkamlaş (15 daqiqa)", "goal": "Kiçik guruhlarda işlab, bir-birining javoblarini baholaş va töldiriş orqali bilimlarni mustahkamlaş.", "steps": ["Guruh 3 ta kiçik guruhga bölinadi (“Ibn Sino”, “Gelmgols”, “Filatov”).", "Har bir guruh flipçart varağida öz savoliga javob yozadi (5 daqiqa).", "Varaqlar soat mili böyiça almaştiriladi, har bir guruh boşqa guruh javobini boşqa rangli marker bilan töldiradi.", "Varaq egasiga qaytgaç, guruh sardori yakuniy javobni taqdim etadi, öqituvçi xulosa qiladi."], "task": ["1-guruh: Oftalmologiya rivojiga hissa qöşgan olimlar va ularning kaşfiyotlari (vaqt çiziği).", "2-guruh: Köz olmasining pardalari va içki muhitlari (sxema çizib, belgilaş).", "3-guruh: Közning 5 ta köriş funksiyasi va ularni tekşiriş usullari (jadval)."]}, {"name": "Insert (belgilar bilan öqiş)", "stage": "Mustaqil öqiş (uyga vazifa)", "goal": "Matnni tanqidiy va diqqat bilan öqiş könikmasini rivojlantiriş.", "steps": ["Öquvçi maʼruza matnini öqib, satr çetiga belgi qöyadi: “V” – bilardim; “+” – yangi maʼlumot; “–” – boşqaça öylardim; “?” – tuşunarsiz.", "Belgilar böyiça jadval töldiriladi.", "Keyingi darsda “?” belgili savollar muhokama qilinadi."], "task": ["“Köruv organining faoliyati” bölimini Insert usulida öqing va jadval tuzing."]}, {"name": "Test va interaktiv maşqlar", "stage": "Nazorat va baholaş (10 daqiqa)", "goal": "Mavzuning özlaştirilişini xolis baholaş.", "steps": ["Öquvçilar RTRdagi 30 savollik testni kompyuter yoki smartfonda yeçadi.", "Natija avtomatik hisoblanadi, xatolar tahlil qilinadi.", "“Atama – taʼrif” moslaştiriş maşqi bajariladi."], "task": ["RTR → “Nazorat” bölimi"]}], "review": ["Oftalmologiya qanday fan va uning asosiy vazifalari nimalardan iborat?", "Nima uçun körişning pasayişi ijtimoiy muammo hisoblanadi?", "Qaysi umumiy kasalliklar közda öz aksini topadi? Misollar keltiring.", "Abu Ali ibn Sino oftalmologiya rivojiga qanday hissa qöşgan?", "Gelmgols, Snellen va Gullstrandning kaşfiyotlarini ayting.", "Köruv analizatori qanday qismlardan iborat?", "Köz olmasining uç pardasini va ularning qismlarini sanab bering.", "Şox pardaning xususiyatlarini ayting. Nima uçun unga tuşgan yot jism kuçli oğriq beradi?", "Qoraçiqning vazifasi nima va uni qaysi muskullar boşqaradi?", "Kiprikli tananing qanday vazifalari bor?", "Tayoqçalar va kolbaçalarning farqi nimada?", "Nima uçun köruv nervi diski “kör doğ” deb ataladi?", "Közning içki tiniq muhitlarini ayting. Köz içi bosimining normasi qança?", "Köz yoşi qanday yöl bilan burun böşliğiga tuşadi?", "Köz olmasini harakatlantiruvçi muskullarni va ularni innervatsiya qiluvçi nervlarni ayting.", "Közning 5 ta asosiy köriş funksiyasini sanab bering.", "Köriş ötkirligi qanday tekşiriladi va hujjatga qanday yoziladi?", "Gemeralopiya nima va uning oldini oliş uçun qanday maslahat beriladi?"], "tasks": [{"title": "1-topşiriq. Köz olmasi sxemasini belgilaş", "text": "RTRning Quyidagi raqamlangan köz olmasi kesimi rasmini daftaringizga çizing va 1–16 raqamlar bilan belgilangan tuzilmalarning nomini yozing. Har bir tuzilmaning bitta asosiy vazifasini körsating.", "check": "Barça 16 tuzilma töğri nomlangan va vazifasi körsatilgan bölsa – “aʼlo”.", "img": "02_koz_kesimi_raqamli.png", "answers": ["Şox parda", "Limb", "Oldingi kamera", "Rangdor parda", "Qoraçiq", "Kiprikli tana", "Sinn boylamlari", "Gavhar", "Sklera (oqsil parda)", "Xususiy tomirli parda", "Tör parda", "Şişasimon tana", "Sariq doğ", "Köruv nervi diski", "Köruv nervi", "Töğri muskul"]}, {"title": "2-topşiriq. Köriş ötkirligini aniqlaş (rolli öyin)", "text": "Juftlikda işlang: biri “hamşira”, biri “bemor”. Sivtsev–Golovin jadvali yordamida 5 m masofadan har bir közning köriş ötkirligini tekşiring va natijani tibbiy hujjat şaklida yozing (Visus OD = …; Visus OS = …). Söng rollarni almaştiring.", "check": "Tekşiruv algoritmi (masofa, yoritiş, közni bosmasdan yopiş, har bir belgiga 2–3 soniya, yozuv şakli) töliq bajarilişi baholanadi."}, {"title": "3-topşiriq. Vaziyatli masala", "text": "Poliklinikaga 45 yoşli haydovçi murojaat qildi. U sönggi oylarda keçqurun maşina haydaganda yölni yomon körayotganini, kunduzi esa körişi yaxşi ekanini aytadi. Ovqatlanişi bir xil, sabzavot va sut mahsulotlarini kam isteʼmol qiladi. Savollar: 1) Bemorda qaysi köriş funksiyasi buzilgan? 2) Bu holat qanday ataladi? 3) Qanday sabab bölişi mumkin? 4) Hamşira qanday maslahatlar beradi?", "check": "Javob: qoronğilik adaptatsiyasi (yoruğlik seziş) buzilgan; gemeralopiya (“tovuq körlik”); ehtimoliy sabab – A vitamini yetişmovçiligi; maslahat – oftalmologga yöllaş, A vitaminiga boy mahsulotlar (sabzi, jigar, sariyoğ, tuxum sariği), keçasi haydaşni vaqtinça çeklaş."}, {"title": "4-topşiriq. Vaziyatli masala", "text": "Hamşira maktabda profilaktik körik ötkazmoqda. 9 yoşli öğil bola Sivtsev jadvalining birinçi qatorini ham 5 m dan öqiy olmadi, lekin 3 m ga yaqinlaşganda öqidi. Savollar: 1) Bolaning köriş ötkirligini Snellen formulasi böyiça hisoblang. 2) Natija qanday yoziladi? 3) Hamşiraning keyingi harakatlari qanday?", "check": "Javob: V = d/D = 3/50 = 0,06; Visus = 0,06; ota-onaga xabar beriş va oftalmolog körigiga yöllaş, tibbiy kartaga qayd etiş."}, {"title": "5-topşiriq. Maşq: Snellen formulasi", "text": "Bemor jadvalning birinçi qatorini (D = 50 m) quyidagi masofalardan öqidi. Köriş ötkirligini hisoblang: a) 4 m; b) 1 m; c) 0,5 m; d) 2,5 m.", "check": "Javoblar: a) 0,08; b) 0,02; c) 0,01; d) 0,05."}], "matching": [["Kolbaçalar", "Kunduzgi va rangli körişni taʼminlovçi fotoretseptorlar"], ["Tayoqçalar", "Ğira-şira va qoronğida körişni taʼminlovçi fotoretseptorlar"], ["Qoraçiq", "Rangdor parda markazidagi, yoruğlik miqdorini boşqaruvçi teşik"], ["Sklera", "Fibroz pardaning oq, noşaffof qismi"], ["Gavhar", "Ikki tomoni qavariq, tiniq, elastik linza"], ["Limb", "Şox pardaning skleraga ötiş joyi"], ["Visus", "Köriş ötkirligi"], ["Fuziya", "Ikki közdagi tasvirlarning yagona tasvirga qöşilişi"]], "structure": [["Taşkiliy qism", "5 daq.", "Salomlaşiş, davomat"], ["Tayanç bilimlarni faollaştiriş", "5 daq.", "Tezkor savol-javob"], ["Yangi mavzu bayoni", "35 daq.", "Taqdimot, video, animatsiya, plakat"], ["Tizimlaştiriş", "7 daq.", "Klaster"], ["Mustahkamlaş", "15 daq.", "“Galereya böylab sayohat”, kiçik guruhlar"], ["Nazorat va baholaş", "10 daq.", "Test, moslaştiriş maşqi"], ["Yakun, uyga vazifa", "3 daq.", "Insert usulida öqiş"]], "literature": ["Yuldaşeva F. S., Yusupova M. S., Aripova S. M. Köz kasalliklari. – Toşkent: Çölpon nomidagi NMIU, 2007.", "Pölatova Ş. A., Aripova G. S., Mirzajonova G. X. va boşq. Kattalarda hamşiralik parvarişi. II qism. – Toşkent, 2012.", "Bikbov M. M. va boşq. Oftalmologiya: darslik (rus tilida). – Moskva: GEOTAR-Media, 2019.", "World Health Organization. World report on vision. – Geneva: WHO, 2019.", "Abu Ali ibn Sino. Tib qonunlari. III kitob. – Toşkent: Fan, 1993 (özbek tilidagi naşr)."], "handouts": [{"title": "Tarqatma material: köz pardalari", "rows": [["Parda", "Qismlari", "Asosiy vazifasi"], ["Taşqi (fibroz)", "Şox parda (1/6), sklera (5/6)", "Şakl beriş, himoya; şox parda – nur ötkaziş va sindiriş"], ["Örta (tomirli)", "Rangdor parda, kiprikli tana, xususiy tomirli parda", "Oziqlantiriş, yoruğlikni boşqariş, köz içi suyuqligi, akkomodatsiya"], ["Içki (tör)", "Optik qism, körmaydigan qism", "Yoruğlikni qabul qilib, nerv impulsiga aylantiriş"]]}], "algorithms": [{"title": "Köriş ötkirligini aniqlaş", "tools": "Sivtsev–Golovin jadvali, Rot apparati, körsatgiç, tösiq", "steps": ["Bemorga tekşiruv maqsadini tuşuntiring va uni jadvaldan 5 m masofaga ötqazing.", "Rot apparatini yoqing: jadval bir tekis yoritilgan bölişi kerak.", "Çap közni tösiq bilan bosmasdan yoping va avval öng közni tekşiring.", "Körsatgiç bilan harflarni yuqori qatordan boşlab körsating, har bir belgiga 2–3 soniya bering.", "Bemor xatosiz öqigan eng pastki qatorni aniqlang (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yöl qöyiladi).", "Xuddi şu tartibda çap közni tekşiring.", "Natijani yozing: Visus OD = …; Visus OS = ….", "Tösiq va körsatgiçni dezinfeksiya qiling."]}], "interactive": ["ray", "pupil", "blind", "snellen"], "type": "Nazariy", "lecture": "<section class=\"lec-sec\" id=\"lec-1\"><h2>1. “Oftalmologiya” fani haqida tuşunça va uning tibbiyot fanlari orasidagi örni</h2><p>Oftalmologiya (yunonça ophthalmos – köz, logos – taʼlimot, fan) – köruv aʼzosining tuzilişi, fiziologiyasi, kasalliklarining kelib çiqiş sabablari, rivojlanişi, belgilari, taşxisi, davolaş va oldini oliş usullarini örganadigan klinik tibbiyot fanidir. Oftalmologiyani qisqaça “köz kasalliklari töğrisidagi fan” deb ham ataşadi. Köz kasalliklari bilan şuğullanuvçi şifokor oftalmolog (okulist), köz bölimi yoki kabinetida işlovçi hamşira esa oftalmologik hamşira deyiladi.</p><p>Inson taşqi muhit töğrisidagi maʼlumotlarning 80–90 foizini köruv aʼzosi orqali qabul qiladi. Köriş qobiliyati odamning öqişi, kasb egallaşi, mehnat qilişi, transport boşqarişi va jamiyatdagi faol hayoti uçun zarur şartdir. Şu sababli körişning pasayişi yoki yöqolişi nafaqat tibbiy, balki katta ijtimoiy muammo hisoblanadi. Jahon soğliqni saqlaş taşkilotining maʼlumotlariga köra, dunyoda kamida 2,2 milliard kişida köriş buzilişi mavjud bölib, ularning deyarli yarmida bu holatning oldini oliş yoki uni öz vaqtida davolaş mumkin edi. Körlik va zaif körişning asosiy sabablari – tuzatilmagan refraksiya anomaliyalari (miopiya, gipermetropiya, astigmatizm), katarakta, glaukoma, qandli diabet asoratlari (diabetik retinopatiya) va yoşga boğliq makula degeneratsiyasidir.</p><h3>Oftalmologiyaning vazifalari</h3><ul><li>köruv aʼzosining normal tuzilişi va faoliyatini örganiş;</li><li>köz kasalliklarining sabablari va rivojlaniş mexanizmlarini aniqlaş;</li><li>közni tekşirişning zamonaviy usullarini işlab çiqiş va amaliyotga joriy etiş;</li><li>köz kasalliklarini konservativ (dori-darmon, fizioterapiya) va jarrohlik (mikroxirurgiya, lazer) usullari bilan davolaş;</li><li>körlik va zaif körişning oldini oliş, aholi örtasida profilaktik köriklar ötkaziş;</li><li>közi ojiz va zaif köruvçi şaxslarni reabilitatsiya qiliş, mehnat qobiliyatini ekspertiza qiliş.</li></ul><h3>Oftalmologiyaning bölimlari</h3><p>Hozirgi zamon oftalmologiyasi bir neçta mustaqil yönalişlarga bölinadi: bolalar oftalmologiyasi, oftalmoxirurgiya (köz mikroxirurgiyasi), lazer oftalmologiyasi, refraksion jarrohlik, glaukomatologiya, kontaktologiya (kontakt linzalar tanlaş), neyrooftalmologiya, oftalmoonkologiya, köz travmatologiyasi va oftalmologik ekspertiza. Har bir yönalişda hamşira şifokorning yaqin yordamçisi sifatida iştirok etadi.</p><h3>Oftalmologiyaning boşqa fanlar bilan boğliqligi</h3><p>Köz organizmning ajralmas qismi bölgani uçun köplab umumiy kasalliklar közda öz aksini topadi. Masalan, gipertoniya kasalligida köz tubi tomirlari torayadi va tör pardada qon quyilişlar paydo böladi; qandli diabetda diabetik retinopatiya va katarakta rivojlanadi; buyrak kasalliklari, ateroskleroz, revmatizm, sil, toksoplazmoz, boş miya ösmalari va jarohatlari ham köz tubida öziga xos özgarişlar beradi. Şu sababli oftalmolog köpinça terapevt, nevropatolog, endokrinolog, pediatr, otorinolaringolog, stomatolog va neyroxirurg bilan hamkorlikda işlaydi. Köz tubini tekşiriş (oftalmoskopiya) köplab umumiy kasalliklarning taşxisi va keçişini baholaşda muhim ahamiyatga ega.</p><p>Oftalmologiya fani normal anatomiya, normal fiziologiya, gistologiya, fizika (optika), lotin tili va tibbiy terminologiya, farmakologiya, mikrobiologiya, terapiya, pediatriya, jarrohlik va hamşiralik işi asoslari fanlari bilan uzviy boğliq. Masalan, közning nur sindiriş tizimini tuşuniş uçun fizikadan optika qonunlarini, köz kasalliklarida qöllaniladigan tomçi dorilarni töğri tayyorlaş va tomiziş uçun esa farmakologiya va hamşiralik manipulyatsiyalarini biliş talab etiladi.</p><h3>Aholiga oftalmologik yordamni taşkil etiş</h3><p>Respublikamizda aholiga köz böyiça tibbiy yordam bosqiçma-bosqiç körsatiladi. Birlamçi böğinda – oilaviy poliklinika va oilaviy şifokor punktlarida köriş ötkirligi aniqlanadi, köz içi bosimi ölçanadi, oddiy yalliğlaniş kasalliklari davolanadi, közga tuşgan yot jismlar olinadi va bemorlar zarur hollarda ixtisoslaşgan muassasaga yöllanadi. Ikkinçi bosqiçda tuman (şahar) tibbiyot birlaşmalarining köz kabinetlari va bölimlari, uçinçi bosqiçda esa viloyat köz kasalliklari şifoxonalari hamda respublika ixtisoslaştirilgan markazlari faoliyat körsatadi. Maktab va maktabgaça taʼlim muassasalarida bolalar har yili körikdan ötkaziladi, 40 yoşdan oşgan barça şaxslarda glaukomani erta aniqlaş maqsadida köz içi bosimini ölçaş tavsiya etiladi. Qandli diabet bilan oğrigan bemorlar yiliga kamida bir marta köz tubi tekşiruvidan ötişi lozim. Bu profilaktik tadbirlarni taşkil etiş va ötkazişda hamşiraning hissasi juda katta.</p><h3>Oftalmologiyada hamşiraning örni</h3><p>Umumiy amaliyot hamşirasi poliklinika, oilaviy şifokor punkti, köz kabineti va statsionarning köz bölimida işlaydi. Uning asosiy vazifalari quyidagilardan iborat: bemorlarni qabul qiliş va tekşiruvga tayyorlaş; köriş ötkirligi, rang köriş va köz içi bosimini aniqlaşda iştirok etiş; şifokor tayinlagan muolajalarni bajariş (konʼyunktiva böşliğiga tomçi dori tomiziş, malham qöyiş, közni yuviş, boğlam qöyiş); operatsiyadan oldin va keyin bemorni parvariş qiliş; közga yot jism tuşganda, kuyiş va jarohatlarda birinçi yordam körsatiş; aholi örtasida köz gigiyenasi va körlikning oldini oliş böyiça sanitariya-oqartuv işlarini olib boriş. Hamşira aseptika va antiseptika qoidalariga qatʼiy rioya qilişi şart, çunki köz infeksiyalari (masalan, adenovirusli konʼyunktivit) asboblar va qöl orqali oson yuqadi.</p><p>Xulosa qilib aytganda, oftalmologiya klinik tibbiyotning mustaqil, ijtimoiy ahamiyati juda yuqori bölgan sohasi bölib, uning yutuqlari köp jihatdan malakali örta tibbiyot xodimlarining – hamşiralarning bilimi va mahoratiga boğliqdir.</p></section><section class=\"lec-sec\" id=\"lec-2\"><h2>2. Oftalmologiya fanining rivojlaniş tarixi</h2><p>Köz kasalliklari haqidagi dastlabki maʼlumotlar eng qadimgi yozma manbalarda uçraydi. Oftalmologiya tarixini şartli ravişda quyidagi davrlarga böliş mumkin: qadimgi dunyo davri, Şarq (örta asrlar) tabobati davri, Yevropa Uyğoniş davri va yangi davr, hozirgi zamon oftalmologiyasi.</p><h3>Qadimgi dunyo davri</h3><figure><img src=\"mavzular/n1/didaktik/07_tarix_vaqt_chizigi.png\" alt=\"Oftalmologiya rivojining asosiy bosqiçlari\" loading=\"lazy\" data-zoom><figcaption>Oftalmologiya rivojining asosiy bosqiçlari</figcaption></figure><p>Qadimgi Misrda miloddan avvalgi XVI asrga oid Ebers papirusida köz kasalliklari va ularni davolaş uçun işlatilgan köplab retseptlar keltirilgan. Bobilda podşo Hammurapi qonunlarida (miloddan avvalgi XVIII asr) köz operatsiyasi muvaffaqiyatli ötsa tabibga tölanadigan haq va muvaffaqiyatsiz bölsa unga beriladigan jazo belgilangan. Qadimgi Hindistonda tabib Suşruta katarakta (köz gavharining xiralaşişi)ni gavharni köz içiga tuşirib yuboriş usuli bilan operatsiya qilgan va 70 dan ortiq köz kasalligini tasvirlagan.</p><p>Qadimgi Yunonistonda Gippokrat köz kasalliklarining bir qança turlarini (konʼyunktivit, trixiaz, katarakta) tasvirlagan. Rimlik olim Aul Korneliy Sels (I asr) katarakta operatsiyasini batafsil bayon qilgan, Galen (II asr) esa köz anatomiyasi va köruv nervi haqida muhim maʼlumotlar qoldirgan. Ammo bu davrda közning nur sindiriş vazifasi notöğri tuşunilgan: tasvirni köz gavhari qabul qiladi, deb hisoblangan.</p><h3>Şarq tabobati davri (IX–XIII asrlar)</h3><p>Örta asrlarda oftalmologiya Şarq mamlakatlarida, jumladan, Markaziy Osiyoda yuqori darajada rivojlandi. Bu davrda köz tabiblari “kahhol” deb atalgan. Hunayn ibn Ishoq (IX asr) “Köz haqida ön maqola” asarini yozdi – bu oftalmologiyaga oid eng qadimgi tizimli darsliklardan biri hisoblanadi. Ali ibn Iso al-Kahhol (X–XI asrlar) 130 ga yaqin köz kasalligini tasvirlagan “Köz tabiblari uçun eslatma” kitobini yaratdi. Ammor al-Mavsiliy kataraktani içi böş ignasimon asbob yordamida sörib oliş usulini taklif qildi. Ibn al-Haysam (Alhazen) “Optika kitobi”da yoruğlik közga taşqaridan tuşişini va köriş jarayonini ilmiy asosda tuşuntirdi.</p><p>Buyuk vatandoşimiz Abu Ali ibn Sino (980–1037) “Tib qonunlari” asarining uçinçi kitobida közning anatomiyasi, fiziologiyasi va kasalliklariga keng örin ajratgan. U közning olti taşqi muskulini, köruv nervi va uning kesişmasini tasvirlagan, köz kasalliklarini davolaş uçun köplab dori-darmon va jarrohlik usullarini bayon qilgan, köz gigiyenasiga katta eʼtibor bergan. Ibn Sino traxoma, katarakta, qovoq kasalliklari va “tungi körlik” haqida qimmatli maʼlumotlar qoldirgan. Uning asarlari lotin tiliga tarjima qilinib, bir neça asr davomida Yevropa universitetlarida asosiy darslik bölib xizmat qilgan.</p><h3>Yevropa Uyğoniş davri va yangi davr (XVI–XIX asrlar)</h3><p>1604-yilda nemis olimi Iogann Kepler tasvir tör pardada hosil bölişini isbotladi, gavhar esa nur sindiruvçi linza vazifasini bajarişini körsatdi. 1748-yilda fransuz jarrohi Jak Daviel kataraktani közdan çiqarib oliş (ekstraksiya) operatsiyasini birinçi bölib amalga oşirdi. XIX asrda oftalmologiya mustaqil fan sifatida şakllandi: 1851-yilda German Gelmgols köz közgusi – oftalmoskopni ixtiro qildi va köz tubini tirik odamda köriş imkoniyati paydo böldi. Gollandiyalik olim Frans Donders közning refraksiyasi va akkomodatsiyasi haqidagi taʼlimotni yaratdi, German Snellen esa 1862-yilda köriş ötkirligini aniqlaş jadvalini taklif qildi. Albrext fon Grefe glaukomani jarrohlik yöli bilan davolaş (iridektomiya) usulini işlab çiqdi. 1911-yilda şved olimi Allvar Gullstrand közning optik tizimini örgangani uçun Nobel mukofotiga sazovor böldi; u yorituvçi tirqişli lampa – biomikroskopni ham ixtiro qilgan.</p><h3>XX asr va hozirgi zamon oftalmologiyasi</h3><p>XX asrda oftalmologiya jadal rivojlandi. Akademik V. P. Filatov şox pardani köçirib ötkaziş (keratoplastika) usulini takomillaştirdi va töqima terapiyasi taʼlimotini yaratdi. Akademik S. N. Fyodorov köz mikroxirurgiyasi rivojiga katta hissa qöşib, sunʼiy gavhar (intraokulyar linza) qöyiş va miopiyani jarrohlik yöli bilan tuzatiş usullarini keng joriy etdi. XX asrning ikkinçi yarmida lazer texnologiyalari, ultratovuş tekşiruvi, kompyuter perimetriyasi, optik kogerent tomografiya (OKT) kabi zamonaviy taşxis usullari amaliyotga kirdi.</p><p>Özbekistonda oftalmologiyaning ilmiy asosda rivojlanişi XX asr boşlarida Toşkentda tibbiyot fakulteti va köz kasalliklari kafedrasi taşkil etilişi bilan boşlandi. Öşa davrda aholi orasida keng tarqalgan traxoma kasalligiga qarşi maxsus traxoma punktlari va dispanserlar tarmoği tuzildi, natijada traxoma ommaviy kasallik sifatida tugatildi. Hozirgi kunda respublikamizda Respublika ixtisoslaştirilgan köz mikroxirurgiyasi ilmiy-amaliy tibbiyot markazi va uning hududiy filiallari, viloyat köz kasalliklari şifoxonalari faoliyat körsatmoqda. Kataraktani fakoemulsifikatsiya usulida olib taşlaş, glaukoma va tör pardaning lazer bilan davolaş, refraksion lazer operatsiyalari muvaffaqiyatli bajarilmoqda.</p><p>Oftalmologiya tarixini biliş hamşiraga bugungi zamonaviy tekşiriş va davolaş usullarining kelib çiqişini tuşunişga, buyuk ajdodlarimiz merosi bilan faxrlanişga va kasbiga masʼuliyat bilan yondaşişga yordam beradi.</p><div class=\"tbl\"><table><thead><tr><th>Davr / sana</th><th>Olim yoki manba</th><th>Hissasi</th></tr></thead><tbody><tr><td>Mil. avv. XVI asr</td><td>Ebers papirusi (Misr)</td><td>Köz kasalliklarini davolaş retseptlari</td></tr><tr><td>Mil. avv. VI asr (taxm.)</td><td>Suşruta (Hindiston)</td><td>Katarakta operatsiyasi, 70 dan ortiq köz kasalligi tasviri</td></tr><tr><td>IX asr</td><td>Hunayn ibn Ishoq</td><td>“Köz haqida ön maqola” darsligi</td></tr><tr><td>X–XI asrlar</td><td>Abu Ali ibn Sino</td><td>“Tib qonunlari”ning 3-kitobida köz anatomiyasi va kasalliklari</td></tr><tr><td>1604-yil</td><td>I. Kepler</td><td>Tasvir tör pardada hosil bölişini isbotladi</td></tr><tr><td>1748-yil</td><td>J. Daviel</td><td>Katarakta ekstraksiyasi operatsiyasi</td></tr><tr><td>1851-yil</td><td>G. Gelmgols</td><td>Oftalmoskopni ixtiro qildi</td></tr><tr><td>1862-yil</td><td>G. Snellen</td><td>Köriş ötkirligini aniqlaş jadvali</td></tr><tr><td>1911-yil</td><td>A. Gullstrand</td><td>Köz optikasi, tirqişli lampa; Nobel mukofoti</td></tr><tr><td>XX asr</td><td>V. P. Filatov, S. N. Fyodorov</td><td>Keratoplastika, köz mikroxirurgiyasi, sunʼiy gavhar</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-3\"><h2>3. Köruv organi anatomiyasi</h2><p>Köruv organi (organum visus) köruv analizatorining periferik qismi hisoblanadi. I. P. Pavlov taʼlimotiga köra, har bir analizator uç qismdan iborat. Köruv analizatori tarkibiga quyidagilar kiradi:</p><ul><li>periferik (qabul qiluvçi) qism – köz olmasi va uning tör pardasidagi yoruğlik sezuvçi hujayralar;</li><li>ötkazuvçi yöllar – köruv nervi, köruv nervlarining kesişmasi (xiazma), köruv yöllari (traktlar), taşqi tizzasimon tanalar va köruv nurlanişi;</li><li>markaziy (pöstloq) qism – boş miya katta yarim şarlarining ensa bölagidagi şporasimon egat atrofida joylaşgan köriş markazi.</li></ul><p>Köriş aʼzosi anatomik jihatdan köz olmasi (bulbus oculi) va közning yordamçi apparatidan iborat. Yordamçi apparatga köz kosasi (orbita), qovoqlar, konʼyunktiva, köz yoşi aʼzolari va köz olmasini harakatlantiruvçi muskullar kiradi.</p><figure><img src=\"mavzular/n1/didaktik/03_koruv_yoli.png\" alt=\"1-rasm. Köruv analizatorining tuzilişi\" loading=\"lazy\" data-zoom><figcaption>1-rasm. Köruv analizatorining tuzilişi</figcaption></figure><h3>Köz olmasi</h3><p>Köz olmasi şarsimon şaklga ega bölib, köz kosasining old qismida joylaşgan. Katta yoşli odamda uning old-orqa ölçami (öqi) örtaça 24 mm, köndalang ölçami 23,5 mm, vertikal ölçami 23 mm, massasi 7–8 g ni taşkil etadi. Yangi tuğilgan çaqaloqda köz öqi taxminan 16–18 mm böladi. Köz olmasining old qismidagi eng börtib çiqqan nuqtasi old qutb, orqa qismidagisi esa orqa qutb deb ataladi. Köz olmasi devori uçta pardadan – taşqi (fibroz), örta (tomirli) va içki (tör) pardalardan tuzilgan, uning içi esa nur ötkazuvçi tiniq muhitlar bilan tölgan.</p><h3>Taşqi – fibroz parda</h3><p>Fibroz parda ziç biriktiruvçi töqimadan iborat bölib, közga şakl beradi va içki tuzilmalarni himoya qiladi. U ikki qismdan – oldingi tiniq şox parda va orqadagi noşaffof oqsil pardadan taşkil topgan.</p><figure><img src=\"mavzular/n1/didaktik/01_koz_kesimi_belgili.png\" alt=\"2-rasm. Köz olmasining gorizontal kesimi\" loading=\"lazy\" data-zoom><figcaption>2-rasm. Köz olmasining gorizontal kesimi</figcaption></figure><p>Şox parda (cornea) fibroz pardaning 1/6 qismini egallaydi. U tiniq, yaltiroq, silliq, sferik va öta sezgir. Katta yoşdagi odamda şox pardaning gorizontal diametri 11–12 mm, yangi tuğilgan çaqaloqda esa 9–10 mm atrofida böladi. Qalinligi markazida 0,5–0,6 mm, çekkasida 1 mm gaça. Şox parda beş qavatdan iborat: oldingi epiteliy, Boumen membranasi, xususiy modda (stroma), Descemet membranasi va orqa epiteliy (endoteliy). Şox pardada qon tomirlari bölmaydi, lekin u uç şoxli nervning tolalariga juda boy, şuning uçun uning yuzasiga eng kiçik yot jism tuşsa ham kuçli oğriq, köz yoşlanişi va qovoqlarning qisilişi (himoya refleksi) yuzaga keladi. Şox parda köz içi suyuqligi, köz yoşi pardasi va limb atrofidagi qon tomirlar töri hisobiga oziqlanadi. Uning asosiy vazifasi – nurni ötkaziş va sindiriş (sindiriş kuçi 40–43 dioptriya).</p><p>Oqsil parda (sclera) fibroz pardaning 5/6 qismini taşkil etadi. U oq rangli, noşaffof, ziç kollagen tolalardan iborat, qalinligi 0,3–1 mm. Bolalarda sklera yupqa bölgani uçun kökimtir tusda, keksalarda esa sarğişroq körinadi. Orqa qutbda sklera ğalvirsimon plastinkani hosil qiladi, uning teşiklaridan köruv nervi tolalari çiqib ketadi. Skleraga közni harakatlantiruvçi muskullar birikadi. Şox pardaning skleraga ötiş joyi limb deb ataladi (kengligi taxminan 1 mm). Sklera közga şakl beradi va içki pardalarni himoya qiladi.</p><h3>Örta – tomirli parda</h3><p>Tomirli parda qon tomirlariga boy bölib, közning içki tuzilmalarini oziqlantiradi. U uç qismdan iborat: rangdor parda, kiprikli (kipriksimon) tana va xususiy tomirli parda.</p><p>Rangdor parda (iris) tomirli pardaning oldingi qismi bölib, şox parda orqasida vertikal holatda joylaşgan. Uning rangi tarkibidagi pigment miqdoriga boğliq (kök, kulrang, yaşil, jigarrang). Rangdor pardaning markazida yumaloq teşik – qoraçiq (pupilla) bor, normada uning diametri 3–4 mm. Rangdor pardada ikki silliq muskul joylaşgan: qoraçiqni toraytiruvçi muskul (közni harakatlantiruvçi nervning parasimpatik tolalari innervatsiya qiladi) va qoraçiqni kengaytiruvçi muskul (simpatik nerv tolalari innervatsiya qiladi). Qoraçiq yoruğlikda torayadi, qoronğilikda kengayadi, yaʼni u fotoapparatning diafragmasi kabi közga tuşadigan yoruğlik miqdorini boşqaradi.</p><p>Kiprikli tana (corpus ciliare) rangdor parda bilan xususiy tomirli parda örtasida halqa şaklida joylaşgan. Uning ösimtalari köz içi suyuqligini işlab çiqaradi. Kiprikli tanadagi muskul Sinn boylamlari orqali gavharga taʼsir etib, uning egriligini özgartiradi va akkomodatsiyani – közning turli masofadagi narsalarni aniq körişga moslaşişini taʼminlaydi. Kiprikli tana yalliğlanganda (iridotsiklit) közni bosib körganda oğriq paydo böladi.</p><p>Xususiy tomirli parda (çorioidea) tomirli pardaning orqa, eng katta qismi bölib, sklera bilan tör parda örtasida joylaşgan. U asosan qon tomirlardan tuzilgan va tör pardaning taşqi qavatlarini, ayniqsa yoruğlik sezuvçi hujayralarni oziqlantiradi.</p><h3>Içki – tör parda</h3><p>Tör parda (retina) köz olmasining eng içki, yupqa, tiniq pardasi bölib, yoruğlik taʼsirini nerv impulsiga aylantiradi. U ikki qismdan iborat: optik (köruvçi) qism – tör pardaning orqadagi 2/3 qismi, va körmaydigan qism – kiprikli tana va rangdor pardaning orqa yuzasini qoplab turadi. Optik qism mikroskopik jihatdan 10 qavatdan tuzilgan. Uning eng muhim hujayralari – yoruğlik sezuvçi fotoretseptorlar: tayoqçalar va kolbaçalar.</p><ul><li>Tayoqçalar soni taxminan 120–130 million, ular asosan tör pardaning periferik qismida joylaşgan; kuçsiz yoruğlikni sezadi va ğira-şira hamda qoronğida körişni taʼminlaydi. Tayoqçalarda köruv purpuri – rodopsin bor, uning hosil bölişi uçun A vitamini zarur.</li><li>Kolbaçalar soni taxminan 6–7 million, ular asosan markazda – sariq doğda töplangan; kunduzgi yoruğlikda işlaydi, narsalarning mayda qismlarini va rangini farqlaşni taʼminlaydi.</li></ul><p>Köz tubida ikki muhim tuzilma körinadi. Sariq doğ (macula lutea) – tör pardaning markazidagi taxminan 5 mm li soha bölib, uning örtasidagi markaziy çuqurça (fovea) faqat kolbaçalardan iborat va eng aniq köriş nuqtasi hisoblanadi. Köruv nervi diski (sörğiçi) – köruv nervi tolalarining köz olmasidan çiqiş joyi, diametri 1,5–1,8 mm. Bu sohada fotoretseptorlar bölmagani uçun u körmaydi va “kör doğ” (Mariott doği) deb ataladi. Köruv nervi diskining markazidan tör pardaning markaziy arteriyasi va venasi çiqadi.</p><h3>Közning içki tiniq muhitlari</h3><p>Köz olmasining içida nur ötkazuvçi va nur sindiruvçi tiniq muhitlar joylaşgan: köz içi suyuqligi, gavhar va şişasimon tana. Şox parda bilan birgalikda ular közning optik tizimini hosil qiladi.</p><ul><li>Köz içi suyuqligi kiprikli tanada işlab çiqariladi va közning oldingi kamerasi (şox parda bilan rangdor parda orasidagi böşliq, çuqurligi markazda 3–3,5 mm) hamda orqa kamerasini (rangdor parda bilan gavhar orasidagi böşliq) töldiradi. U şox parda va gavharni oziqlantiradi. Suyuqlik asosan oldingi kamera burçagi va Şlemm kanali orqali vena tizimiga çiqib ketadi. Suyuqlikning işlab çiqarilişi va çiqib ketişi orasidagi muvozanat köz içi bosimini belgilaydi; uning normasi Maklakov tonometri böyiça 18–26 mm sim. ust. Uşbu muvozanat buzilsa, glaukoma rivojlanişi mumkin.</li><li>Gavhar (lens) – ikki tomoni qavariq, tiniq, elastik linza. Diametri 9–10 mm, qalinligi 3,5–5 mm, sindiriş kuçi taxminan 18–20 dioptriya. Gavharda qon tomirlari va nervlar yöq, u kiprikli tanaga Sinn boylamlari yordamida osilib turadi. Yoş ötişi bilan gavhar elastikligini yöqotadi (presbiopiya), uning xiralaşişi esa katarakta deb ataladi.</li><li>Şişasimon tana (corpus vitreum) – gavhar orqasida joylaşgan tiniq, iviqsimon modda; köz olmasi hajmining taxminan 2/3 qismini (4 ml ga yaqin) egallaydi, 98–99 foizi suvdan iborat. U közning şaklini saqlaydi va tör pardani tomirli pardaga bosib turadi.</li></ul><h3>Közning yordamçi apparati</h3><p>Köz kosasi (orbita) – yetti suyakdan (peşona, yonoq, yuqori jağ, ğalvirsimon, ponasimon, köz yoşi va tanglay suyaklari) hosil bölgan tört qirrali piramida şaklidagi böşliq, çuqurligi 4–5 sm. Unda köz olmasi, muskullar, nervlar, qon tomirlar va yoğ töqimasi joylaşgan. Köz kosasi közni taşqi taʼsirlardan himoya qiladi.</p><p>Qovoqlar (palpebrae) – yuqori va pastki teri-muskul burmalari bölib, közni yoruğlik, çang va şikastlardan himoya qiladi, köz pirpiratiş orqali köz yoşini şox parda yuzasiga bir tekis yoyadi. Qovoq terisi juda yupqa va teri osti kletçatkasi böş bölgani uçun yalliğlanişda va jarohatda qovoqlar tez şişadi. Qovoq tarkibida közning aylana muskuli (yuz nervi innervatsiya qiladi), yuqori qovoqni kötaruvçi muskul (közni harakatlantiruvçi nerv innervatsiya qiladi), toğaysimon plastinka va uning içidagi meybomiy bezlari bor. Qovoqlarning çetida kipriklar ösadi, ularning ildizida yoğ va ter bezlari joylaşgan. Qovoqlar orasidagi tirqiş köz tirqişi deb ataladi.</p><p>Konʼyunktiva (şilliq parda) – qovoqlarning içki yuzasini va köz olmasining old qismini (şox pardagaça) qoplab turuvçi yupqa, tiniq şilliq parda. Uning qovoq konʼyunktivasi, ötiş burmalari va köz olmasi konʼyunktivasi qismlari farqlanadi. Qovoq konʼyunktivasi bilan köz olmasi konʼyunktivasi orasidagi yopiq böşliq konʼyunktiva böşliği deyiladi – hamşira tomçi dori va malhamni aynan şu böşliqqa, asosan pastki ötiş burmasiga yuboradi.</p><p>Köz yoşi aʼzolari köz yoşi işlab çiqaruvçi va uni ötkazuvçi qismlardan iborat. Köz yoşi bezi köz kosasining yuqori-taşqi burçagida joylaşgan. Köz yoşi şox parda yuzasini namlab, oziqlantiradi, mikroblardan tozalaydi (tarkibida lizotsim bor) va közning içki burçagidagi köz yoşi kölçasiga töplanadi. Söngra u yuqori va pastki köz yoşi nuqtalari, köz yoşi nayçalari, köz yoşi xaltasi va burun-köz yoşi kanali orqali burunning pastki yöliga oqib tuşadi. Bir keça-kunduzda normada 0,5–1 ml köz yoşi ajraladi.</p><p>Köz olmasini harakatlantiruvçi muskullar oltita: törtta töğri (yuqori, pastki, içki, taşqi) va ikkita qiyşiq (yuqori va pastki) muskul. Ular köz olmasini barça yönalişlarda harakatlantiradi va ikki közning birgalikdagi muvofiq harakatini taʼminlaydi. Yuqori qiyşiq muskulni ğaltak nervi (IV juft), taşqi töğri muskulni uzoqlaştiruvçi nerv (VI juft), qolgan muskullarni közni harakatlantiruvçi nerv (III juft) innervatsiya qiladi. Muskullar faoliyati buzilganda ğilaylik va közda ikkilanib köriş paydo böladi.</p><p>Köz va uning yordamçi apparati asosan içki uyqu arteriyasining tarmoği – köz arteriyasi orqali qon bilan taʼminlanadi. Venoz qon köz venalari orqali ğorsimon sinusga quyiladi; yuz venalari bilan boğlanişi sababli yuzdagi yiringli jarayonlar (masalan, çipqonni siqiş) infeksiyaning miyaga tarqalişiga olib kelişi mumkin. Hamşira buni bemorlarga albatta tuşuntirişi lozim.</p><div class=\"tbl\"><table><thead><tr><th>Parda</th><th>Qismlari</th><th>Asosiy vazifasi</th></tr></thead><tbody><tr><td>Taşqi (fibroz)</td><td>Şox parda (1/6), oqsil parda – sklera (5/6)</td><td>Şakl beriş, himoya, nur ötkaziş va sindiriş (şox parda)</td></tr><tr><td>Örta (tomirli)</td><td>Rangdor parda, kiprikli tana, xususiy tomirli parda</td><td>Oziqlantiriş, yoruğlik miqdorini boşqariş, köz içi suyuqligi işlab çiqariş, akkomodatsiya</td></tr><tr><td>Içki (tör)</td><td>Optik qism, körmaydigan qism</td><td>Yoruğlikni qabul qiliş va nerv impulsiga aylantiriş</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-4\"><h2>4. Köruv organining faoliyati (köriş funksiyalari)</h2><p>Köriş jarayoni quyidagiça amalga oşadi: narsadan qaytgan nurlar şox parda, oldingi kamera suyuqligi, qoraçiq, gavhar va şişasimon tanadan ötib sinadi va tör pardaga, aniqroği sariq doğga, kiçraytirilgan va teskari tasvir holida tuşadi. Fotoretseptorlarda kimyoviy reaksiya natijasida nerv impulsi hosil böladi va u köruv yöllari orqali boş miya pöstloğining ensa bölagiga yetib boradi. Köriş markazida tasvir tahlil qilinadi va biz narsani töğri holatda, rangli va hajmli köramiz.</p><p>Közning asosiy köriş funksiyalari beşta: markaziy köriş, periferik köriş, rang köriş, yoruğlik seziş va binokulyar köriş. Ularni tekşirişda hamşira faol iştirok etadi.</p><h3>Markaziy köriş (köriş ötkirligi)</h3><p>Markaziy köriş sariq doğning markaziy çuqurçasidagi kolbaçalar faoliyati bilan boğliq bölib, narsalarning şakli va mayda qismlarini aniq farqlaşni taʼminlaydi. Uning miqdoriy körsatkiçi köriş ötkirligi (visus) deb ataladi – közning ikki nuqtani alohida-alohida köra oliş qobiliyati. Normal köriş ötkirligi 1,0 (100 foiz) ga teng.</p><p>Köriş ötkirligi Sivtsev–Golovin jadvali yordamida 5 metr masofadan tekşiriladi. Jadval 12 qatordan iborat bölib, harflar yuqoridan pastga kiçrayib boradi; har bir qator yonida köriş ötkirligi (V) körsatilgan (0,1 dan 2,0 gaça). Maktabgaça yoşdagi bolalarni tekşiriş uçun rasmli Orlova jadvali işlatiladi. Jadval Rot apparatida bir tekis yoritilgan bölişi kerak (taxminan 700 lyuks).</p><p>Tekşiriş tartibi: bemor jadvaldan 5 m masofada ötiradi; har bir köz alohida tekşiriladi – avval öng (OD), keyin çap (OS) köz; tekşirilmayotgan köz maxsus tösiq (şitok) bilan bosilmasdan yopiladi; hamşira körsatgiç bilan harflarni yuqori qatordan boşlab körsatadi, har bir belgini öqiş uçun 2–3 soniya beriladi. Köriş ötkirligi bemor xatosiz öqiy olgan eng pastki qatorga köra aniqlanadi (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yöl qöyiladi). Natija tibbiy hujjatga quyidagiça yoziladi: Visus OD = 1,0; Visus OS = 0,8.</p><p>Agar bemor 5 m dan eng yuqori qatorni köra olmasa, u jadvalga yaqinlaştiriladi va Snellen formulasi böyiça hisoblanadi: V = d / D, bu yerda d – bemor eng yuqori qatorni öqigan masofa, D – şu qatorni normal köz köradigan masofa (50 m). Masalan, bemor birinçi qatorni 2 m dan öqisa, V = 2/50 = 0,04. Köriş ötkirligi 0,005 dan past bölsa, yoruğlik sezişi tekşiriladi. Qoronği xonada közga turli tomondan yoruğlik tuşiriladi: bemor yoruğlikni sezsa va uning yönalişini töğri aniqlasa – “yoruğlikni töğri proyeksiya bilan sezadi” (1/∞ pr. l. certa), notöğri aniqlasa – “notöğri proyeksiya bilan” deb yoziladi. Yoruğlikni umuman sezmasa, köriş ötkirligi nolga teng (V = 0) – bu mutlaq körlikdir.</p><h3>Periferik köriş (köruv maydoni)</h3><figure><img src=\"mavzular/n1/didaktik/04_sivtsev_jadvali.png\" alt=\"3-rasm. Sivtsev–Golovin jadvali\" loading=\"lazy\" data-zoom><figcaption>3-rasm. Sivtsev–Golovin jadvali</figcaption></figure><p>Periferik köriş tör pardaning çekka qismlaridagi asosan tayoqçalar faoliyatiga boğliq bölib, atrofdagi fazoda möljal oliş, harakatlanuvçi narsalarni seziş va qoronğida yöl topişni taʼminlaydi. Köz bir nuqtaga qimirlamay qaraganda bir vaqtda köra oladigan fazo köruv maydoni deyiladi. Uni taxminiy (nazorat) usulda – şifokor yoki hamşira öz köruv maydoni bilan taqqoslab, yoki aniq usulda – perimetr asbobida (perimetriya) tekşiriladi. Oq rang uçun köruv maydonining normal çegaralari: taşqi tomonda 90°, pastki tomonda 65°, içki tomonda 55°, yuqori tomonda 50° atrofida. Köruv maydonining torayişi glaukoma, tör parda va köruv nervi kasalliklarida, uning içida körmaydigan qismlar (skotomalar) paydo bölişi esa tör parda va köruv yöllari zararlanganda kuzatiladi. Köruv maydonining yarmi tuşib qolişi gemianopsiya deb ataladi va boş miya kasalliklarida uçraydi.</p><h3>Rang köriş</h3><p>Rang köriş kolbaçalar faoliyati bilan boğliq. Yung–Gelmgols uç komponentli nazariyasiga köra, tör pardada uç xil kolbaça mavjud: qizil, yaşil va kök ranglarni sezuvçi kolbaçalar. Ularning turliça qözğalişi natijasida biz barça rang va tuslarni köramiz. Uç rangni ham normal seziş normal trixromaziya deyiladi. Rang körişning tuğma buzilişi köpinça erkaklarda uçraydi va irsiy yöl bilan (X xromosoma orqali) beriladi. Qizil rangni sezmaslik – protanopiya, yaşil rangni sezmaslik – deyteranopiya, kök rangni sezmaslik – tritanopiya deb ataladi. Qizil va yaşil ranglarni farqlay olmaslik ingliz olimi J. Dalton nomi bilan daltonizm deyiladi. Rang körişning orttirilgan buzilişlari tör parda va köruv nervi kasalliklarida kuzatiladi.</p><p>Rang köriş Rabkin polixromatik jadvallari yordamida tekşiriladi. Jadvallarda bir xil yorqinlikdagi, lekin turli rangdagi doiraçalardan raqam yoki şakl tuzilgan bölib, rang körişi buzilgan odam ularni farqlay olmaydi. Tekşiruv kunduzgi yoruğlikda, 1 m masofada ötkaziladi, har bir jadvalni köriş uçun 5–10 soniya beriladi. Rang körişni tekşiriş haydovçilar, uçuvçilar, temir yöl va dengiz transporti xodimlari, şifokorlar va boşqa bir qator kasb egalarining kasbiy tanlovida majburiydir.</p><figure><img src=\"mavzular/n1/didaktik/05_koruv_maydoni.png\" alt=\"4-rasm. Köruv maydonining normal çegaralari\" loading=\"lazy\" data-zoom><figcaption>4-rasm. Köruv maydonining normal çegaralari</figcaption></figure><h3>Yoruğlik seziş va qoronğilikka moslaşiş</h3><p>Yoruğlik seziş – közning yoruğlikni va uning eng kam miqdorini idrok etiş qobiliyati bölib, asosan tayoqçalar faoliyatiga boğliq. Közning turli yoritilganlik darajasiga moslaşişi adaptatsiya deyiladi. Yoruğ joydan qoronği joyga ötganda köz asta-sekin qoronğilikka moslaşadi (qoronğilik adaptatsiyasi 40–60 daqiqa davom etadi), aksinça, yoruğlikka moslaşiş tez – 1 daqiqa atrofida yuz beradi. Qoronğilik adaptatsiyasining buzilişi gemeralopiya (xalq orasida “tovuq körlik”) deb ataladi: bemor kunduzi yaxşi köradi, ğira-şira va qoronğida esa körmaydi. U köpinça A vitamini yetişmovçiligida (orttirilgan, funksional gemeralopiya) yoki tör parda kasalliklarida (tuğma, simptomatik gemeralopiya) uçraydi. Funksional gemeralopiyada A vitamini va unga boy mahsulotlar (sabzi, jigar, sariyoğ, tuxum sariği) tavsiya etiladi.</p><figure><img src=\"mavzular/n1/didaktik/06_rang_plastinka.png\" alt=\"5-rasm. Polixromatik plastinka namunasi (raqam: 74)\" loading=\"lazy\" data-zoom><figcaption>5-rasm. Polixromatik plastinka namunasi (raqam: 74)</figcaption></figure><h3>Binokulyar köriş</h3><p>Binokulyar köriş – ikki köz bilan birgalikda körişda ikkala közdagi tasvirlarning boş miya pöstloğida yagona tasvirga qöşilişi (fuziya). Binokulyar köriş narsalarni hajmli (stereoskopik) köriş, ularning çuqurligi va masofasini aniq baholaş imkonini beradi. U bolalarda 3–6 yoşgaça şakllanadi. Binokulyar köriş uçun ikki közning köriş ötkirligi yetarli va bir-biriga yaqin bölişi, köz muskullari muvofiq işlaşi kerak. Ğilaylikda binokulyar köriş buziladi. Binokulyar köriş oddiy sinamalar bilan tekşiriladi: Sokolov sinamasi (“kaftdagi teşik”), qalamlar bilan sinama (bemor qalam uçini ikkinçi qalam uçiga tekkizişi kerak), şuningdek tört nuqtali rang testi asbobida. Binokulyar köriş haydovçi, uçuvçi, jarroh kabi kasblar uçun juda muhim.</p><h3>Köriş funksiyalarini tekşirişda hamşiraning vazifalari</h3><ul><li>tekşiruv xonasi va asboblarni (jadvallar, Rot apparati, körsatgiç, tösiq, Rabkin jadvallari) tayyorlaş;</li><li>bemorga tekşiruvning maqsadi va tartibini tuşuntiriş, uni qulay joylaştiriş;</li><li>har bir közni alohida tekşiriş, közni bosmasdan yopişni nazorat qiliş;</li><li>natijalarni tibbiy hujjatga aniq va töğri yoziş;</li><li>tösiq va körsatgiçni har bir bemordan keyin dezinfeksiya qiliş;</li><li>aholiga köriş gigiyenasi (töğri yoritiş, kompyuterda işlaş tartibi, 20–20–20 qoidasi) böyiça maslahat beriş.</li></ul><p>Xulosa: köruv organi murakkab tuzilgan, nozik va öta muhim aʼzo. Uning tuzilişi va funksiyalarini çuqur biliş hamşiraga köz kasalliklarini erta aniqlaş, tekşiruvlarni töğri ötkaziş, bemorlarni sifatli parvariş qiliş va aholi örtasida profilaktik işlarni samarali taşkil etiş imkonini beradi.</p></section>", "lecture_toc": ["1. “Oftalmologiya” fani haqida tuşunça va uning tibbiyot fanlari orasidagi örni", "2. Oftalmologiya fanining rivojlaniş tarixi", "3. Köruv organi anatomiyasi", "4. Köruv organining faoliyati (köriş funksiyalari)"], "tests": [{"q": "“Oftalmologiya” sözi qaysi tildan olingan?", "o": ["Yunon tilidan", "Lotin tilidan", "Arab tilidan", "Fors tilidan"], "a": 0}, {"q": "Inson taşqi muhit haqidagi maʼlumotning taxminan qança qismini köriş orqali oladi?", "o": ["80–90 foizini", "30–40 foizini", "50 foizini", "10–20 foizini"], "a": 0}, {"q": "Abu Ali ibn Sino köz kasalliklarini “Tib qonunlari”ning qaysi kitobida bayon qilgan?", "o": ["3-kitobida", "1-kitobida", "5-kitobida", "2-kitobida"], "a": 0}, {"q": "Oftalmoskopni kim ixtiro qilgan?", "o": ["G. Gelmgols", "G. Snellen", "J. Daviel", "I. Kepler"], "a": 0}, {"q": "Katarakta ekstraksiyasini birinçi bölib bajargan olim:", "o": ["J. Daviel", "A. Gullstrand", "F. Donders", "V. P. Filatov"], "a": 0}, {"q": "Tasvir tör pardada hosil bölişini kim isbotlagan?", "o": ["I. Kepler", "Galen", "Gippokrat", "G. Snellen"], "a": 0}, {"q": "Köruv analizatori qaysi qismlardan iborat?", "o": ["Periferik qism, ötkazuvçi yöllar, pöstloq markazi", "Köz olmasi, qovoqlar, konʼyunktiva", "Şox parda, gavhar, tör parda", "Köz kosasi, muskullar, köz yoşi bezi"], "a": 0}, {"q": "Köriş markazi boş miyaning qaysi bölagida joylaşgan?", "o": ["Ensa bölagida", "Peşona bölagida", "Çakka bölagida", "Tepa bölagida"], "a": 0}, {"q": "Köz olmasi devori qaysi pardalardan iborat?", "o": ["Fibroz, tomirli, tör parda", "Fibroz, şilliq, tör parda", "Şox, oqsil, şilliq parda", "Tomirli, şilliq, muskul qavat"], "a": 0}, {"q": "Fibroz parda qaysi qismlardan taşkil topgan?", "o": ["Şox parda va sklera", "Şox parda va rangdor parda", "Sklera va konʼyunktiva", "Rangdor parda va kiprikli tana"], "a": 0}, {"q": "Katta yoşli odamda şox pardaning gorizontal diametri:", "o": ["11–12 mm", "8 mm", "15 mm", "20 mm"], "a": 0}, {"q": "Şox parda qanday oziqlanadi?", "o": ["Köz içi suyuqligi, köz yoşi va limb tomirlari hisobiga", "Faqat öz qon tomirlari orqali", "Şişasimon tana orqali", "Köruv nervi orqali"], "a": 0}, {"q": "Qon tomirlari yöq, lekin nerv tolalariga juda boy parda:", "o": ["Şox parda", "Sklera", "Xususiy tomirli parda", "Kiprikli tana"], "a": 0}, {"q": "Skleraning asosiy vazifasi:", "o": ["Közga şakl beriş va himoya qiliş", "Nurni sindiriş", "Akkomodatsiya", "Köz içi suyuqligini işlab çiqariş"], "a": 0}, {"q": "Tomirli parda qanday qismlardan iborat?", "o": ["Rangdor parda, kiprikli tana, xususiy tomirli parda", "Şox parda, sklera, limb", "Gavhar, şişasimon tana", "Sariq doğ, köruv nervi diski"], "a": 0}, {"q": "Qoraçiq közning qaysi qismida joylaşgan?", "o": ["Rangdor pardada", "Şox pardada", "Gavharda", "Tör pardada"], "a": 0}, {"q": "Qoraçiqni toraytiruvçi muskulni qaysi nerv tolalari innervatsiya qiladi?", "o": ["Közni harakatlantiruvçi nervning parasimpatik tolalari", "Simpatik nerv tolalari", "Yuz nervi", "Uç şoxli nerv"], "a": 0}, {"q": "Köz içi suyuqligi qayerda işlab çiqariladi?", "o": ["Kiprikli tanada", "Köz yoşi bezida", "Gavharda", "Şişasimon tanada"], "a": 0}, {"q": "Akkomodatsiyani taʼminlaydigan tuzilma:", "o": ["Kiprikli tana muskuli va gavhar", "Sklera", "Köruv nervi", "Konʼyunktiva"], "a": 0}, {"q": "Kunduzgi va rangli körişni taʼminlovçi hujayralar:", "o": ["Kolbaçalar", "Tayoqçalar", "Ganglioz hujayralar", "Pigment epiteliy"], "a": 0}, {"q": "Tayoqçalardagi köruv purpuri (rodopsin) hosil bölişi uçun qaysi vitamin zarur?", "o": ["A vitamini", "C vitamini", "D vitamini", "B12 vitamini"], "a": 0}, {"q": "Tör pardaning eng aniq köriş nuqtasi:", "o": ["Sariq doğning markaziy çuqurçasi", "Köruv nervi diski", "Tör pardaning periferiyasi", "Tişsimon çiziq"], "a": 0}, {"q": "“Kör doğ” (Mariott doği) qayerda joylaşgan?", "o": ["Köruv nervi diskida", "Sariq doğda", "Şox pardada", "Gavharda"], "a": 0}, {"q": "Közning içki tiniq muhitlari:", "o": ["Köz içi suyuqligi, gavhar, şişasimon tana", "Şox parda, sklera, gavhar", "Rangdor parda, gavhar, qoraçiq", "Konʼyunktiva, köz yoşi, gavhar"], "a": 0}, {"q": "Maklakov tonometri böyiça köz içi bosimining normasi:", "o": ["18–26 mm sim. ust.", "5–10 mm sim. ust.", "30–40 mm sim. ust.", "120/80 mm sim. ust."], "a": 0}, {"q": "Gavharning sindiriş kuçi taxminan:", "o": ["18–20 dioptriya", "40–43 dioptriya", "5 dioptriya", "60 dioptriya"], "a": 0}, {"q": "Köz yoşi bezi qayerda joylaşgan?", "o": ["Köz kosasining yuqori-taşqi burçagida", "Közning içki burçagida", "Pastki qovoqda", "Burun böşliğida"], "a": 0}, {"q": "Köz olmasini harakatlantiruvçi muskullar soni:", "o": ["6 ta", "4 ta", "8 ta", "5 ta"], "a": 0}, {"q": "Taşqi töğri muskulni qaysi nerv innervatsiya qiladi?", "o": ["Uzoqlaştiruvçi nerv (VI juft)", "Ğaltak nervi (IV juft)", "Közni harakatlantiruvçi nerv (III juft)", "Yuz nervi (VII juft)"], "a": 0}, {"q": "Köriş ötkirligi Sivtsev–Golovin jadvali bilan qanday masofadan tekşiriladi?", "o": ["5 m", "1 m", "3 m", "10 m"], "a": 0}, {"q": "Bemor jadvalning birinçi qatorini 1 m dan öqidi. Köriş ötkirligi:", "o": ["0,02", "0,1", "0,2", "0,01"], "a": 0}, {"q": "Oq rang uçun köruv maydonining taşqi çegarasi normada:", "o": ["90°", "50°", "30°", "120°"], "a": 0}, {"q": "Rang köriş qaysi jadvallar yordamida tekşiriladi?", "o": ["Rabkin polixromatik jadvallari", "Sivtsev–Golovin jadvali", "Orlova jadvali", "Snellen jadvali"], "a": 0}, {"q": "Qizil rangni sezmaslik qanday ataladi?", "o": ["Protanopiya", "Deyteranopiya", "Tritanopiya", "Gemianopsiya"], "a": 0}, {"q": "Gemeralopiya (“tovuq körlik”) – bu:", "o": ["Qoronğilik adaptatsiyasining buzilişi", "Rang körişning buzilişi", "Köruv maydonining yarmi tuşib qolişi", "Ikkilanib köriş"], "a": 0}, {"q": "Binokulyar körişni tekşiriş usuli:", "o": ["Sokolov sinamasi (“kaftdagi teşik”)", "Tonometriya", "Perimetriya", "Rabkin jadvallari"], "a": 0}], "gallery": [{"f": "plakat.jpg", "t": "Mavzu böyiça infografika-plakat", "d": "Mavzuning asosiy savollarini yorituvçi körgazmali plakat (muallif işlanmasi)."}, {"f": "01_koz_kesimi_belgili.png", "t": "Köz olmasining kesimi (belgilangan)", "d": "Pardalar, içki muhitlar, köruv nervi va muskullar."}, {"f": "02_koz_kesimi_raqamli.png", "t": "Köz olmasining kesimi (topşiriq uçun)", "d": "1–16 raqamli tuzilmalarni nomlang."}, {"f": "03_koruv_yoli.png", "t": "Köruv analizatori", "d": "Periferik qism, ötkazuvçi yöllar va pöstloq markazi."}, {"f": "08_klaster_koruv_organi.png", "t": "Klaster: köruv organi", "d": "Köz olmasi va yordamçi apparat tuzilmalari."}, {"f": "07_tarix_vaqt_chizigi.png", "t": "Oftalmologiya tarixi", "d": "Qadimgi davrdan XX asrgaça asosiy kaşfiyotlar."}, {"f": "04_sivtsev_jadvali.png", "t": "Sivtsev–Golovin jadvali", "d": "Köriş ötkirligini aniqlaş jadvali namunasi."}, {"f": "05_koruv_maydoni.png", "t": "Köruv maydoni çegaralari", "d": "Öng köz uçun oq rangda normal çegaralar."}, {"f": "06_rang_plastinka.png", "t": "Polixromatik plastinka", "d": "Rang körişni tekşiriş namunasi (norma: 74)."}, {"f": "umumiy_plakat.jpg", "t": "Oftalmologiya: umumiy plakat", "d": "Fan haqida umumiy körgazmali plakat (muallif işlanmasi)."}], "glossary": [{"t": "Adaptatsiya", "l": "adaptatio", "d": "Közning turli yoritilganlik darajasiga moslaşişi (qoronğilik va yoruğlik adaptatsiyasi)."}, {"t": "Akkomodatsiya", "l": "accommodatio", "d": "Közning gavhar egriligini özgartirib, turli masofadagi narsalarni aniq körişga moslaşişi."}, {"t": "Analizator", "l": "analysator", "d": "Taʼsirlarni qabul qiluvçi, ötkazuvçi va tahlil qiluvçi qismlardan iborat nerv tizimi; köruv analizatori."}, {"t": "Binokulyar köriş", "l": "visus binocularis", "d": "Ikki köz bilan birgalikda körib, narsani yagona, hajmli tasvir sifatida idrok etiş."}, {"t": "Daltonizm", "l": "daltonismus", "d": "Qizil va yaşil ranglarni farqlay olmaslik; rang körişning tuğma buzilişi."}, {"t": "Deyteranopiya", "l": "deuteranopia", "d": "Yaşil rangni sezmaslik."}, {"t": "Dioptriya", "l": "dioptria", "d": "Linza yoki optik tizimning sindiriş kuçi birligi (D); fokus masofasi 1 m bölgan linza kuçi."}, {"t": "Fotoretseptorlar", "l": "photoreceptores", "d": "Tör pardaning yoruğlik sezuvçi hujayralari – tayoqçalar va kolbaçalar."}, {"t": "Fuziya", "l": "fusio", "d": "Ikki közdagi tasvirlarning boş miya pöstloğida yagona tasvirga qöşilişi."}, {"t": "Gavhar", "l": "lens", "d": "Rangdor parda va şişasimon tana orasidagi ikki tomoni qavariq, tiniq, elastik linza."}, {"t": "Gemeralopiya", "l": "hemeralopia", "d": "Qoronğilik adaptatsiyasining buzilişi, ğira-şira va qoronğida yomon köriş (“tovuq körlik”)."}, {"t": "Gemianopsiya", "l": "hemianopsia", "d": "Köruv maydonining yarmi tuşib qolişi."}, {"t": "Iris", "l": "iris", "d": "Rangdor parda – tomirli pardaning oldingi qismi, markazida qoraçiq joylaşgan."}, {"t": "Kiprikli tana", "l": "corpus ciliare", "d": "Tomirli pardaning örta qismi; köz içi suyuqligini işlab çiqaradi, akkomodatsiyada qatnaşadi."}, {"t": "Kolbaçalar", "l": "coni", "d": "Kunduzgi va rangli körişni taʼminlovçi fotoretseptorlar; sariq doğda köp."}, {"t": "Konʼyunktiva", "l": "conjunctiva", "d": "Qovoqlarning içki yuzasini va köz olmasining old qismini qoplovçi şilliq parda."}, {"t": "Köruv maydoni", "l": "campus visus", "d": "Köz bir nuqtaga qimirlamay qaraganda bir vaqtda köra oladigan fazo."}, {"t": "Köruv nervi diski", "l": "discus nervi optici", "d": "Köruv nervi tolalarining köz olmasidan çiqiş joyi; “kör doğ”."}, {"t": "Köz içi bosimi", "l": "tensio intraocularis", "d": "Köz içidagi suyuqlik bosimi; Maklakov böyiça normasi 18–26 mm sim. ust."}, {"t": "Limb", "l": "limbus corneae", "d": "Şox pardaning skleraga ötiş joyi, kengligi taxminan 1 mm."}, {"t": "Makula", "l": "macula lutea", "d": "Sariq doğ – tör pardaning eng aniq köriş sohasi."}, {"t": "Oftalmologiya", "l": "ophthalmologia", "d": "Köruv aʼzosining tuzilişi, faoliyati va kasalliklarini örganuvçi tibbiyot fani."}, {"t": "Oftalmoskopiya", "l": "ophthalmoscopia", "d": "Köz tubini maxsus asbob – oftalmoskop yordamida tekşiriş."}, {"t": "Orbita", "l": "orbita", "d": "Köz kosasi – yetti suyakdan hosil bölgan, köz olmasi joylaşgan böşliq."}, {"t": "Perimetriya", "l": "perimetria", "d": "Köruv maydonini perimetr asbobi yordamida tekşiriş."}, {"t": "Presbiopiya", "l": "presbyopia", "d": "Yoşga boğliq akkomodatsiyaning susayişi, yaqindan körişning qiyinlaşişi."}, {"t": "Protanopiya", "l": "protanopia", "d": "Qizil rangni sezmaslik."}, {"t": "Qoraçiq", "l": "pupilla", "d": "Rangdor parda markazidagi yumaloq teşik, közga tuşadigan yoruğlik miqdorini boşqaradi."}, {"t": "Refraksiya", "l": "refractio", "d": "Közning optik tizimida nurlarning sinişi."}, {"t": "Retina", "l": "retina", "d": "Tör parda – yoruğlikni qabul qilib, nerv impulsiga aylantiruvçi içki parda."}, {"t": "Rodopsin", "l": "rhodopsinum", "d": "Tayoqçalardagi köruv purpuri; hosil bölişi uçun A vitamini zarur."}, {"t": "Sklera", "l": "sclera", "d": "Oqsil parda – fibroz pardaning oq, noşaffof qismi."}, {"t": "Skotoma", "l": "scotoma", "d": "Köruv maydoni içidagi körmaydigan soha."}, {"t": "Tayoqçalar", "l": "bacilli", "d": "Ğira-şira va qoronğida körişni taʼminlovçi fotoretseptorlar."}, {"t": "Tonometriya", "l": "tonometria", "d": "Köz içi bosimini ölçaş."}, {"t": "Tritanopiya", "l": "tritanopia", "d": "Kök rangni sezmaslik."}, {"t": "Trixromaziya", "l": "trichromasia", "d": "Uç asosiy rangni (qizil, yaşil, kök) normal seziş."}, {"t": "Visus", "l": "visus", "d": "Köriş ötkirligi – közning ikki nuqtani alohida köra oliş qobiliyati; normasi 1,0."}, {"t": "Xiazma", "l": "chiasma opticum", "d": "Köruv nervlarining qisman kesişgan joyi."}, {"t": "Xorioideya", "l": "chorioidea", "d": "Xususiy tomirli parda – tör pardaning taşqi qavatlarini oziqlantiradi."}, {"t": "Şişasimon tana", "l": "corpus vitreum", "d": "Gavhar orqasidagi tiniq iviqsimon modda, köz hajmining 2/3 qismini egallaydi."}, {"t": "Şox parda", "l": "cornea", "d": "Fibroz pardaning oldingi tiniq qismi; nurni ötkazadi va sindiradi."}], "slides": [{"title": "Oftalmologiyaning rivojlaniş tarixi. Köruv organi anatomiyasi. Közning köriş faoliyati", "note": "Assalomu alaykum, aziz öquvçilar! Bugun “Oftalmologiyada hamşiralik işi” modulining birinçi mavzusi – oftalmologiyaning rivojlaniş tarixi, köruv organi anatomiyasi va közning köriş faoliyati bilan tanişamiz."}, {"title": "Maşğulot rejasi va öqitiş natijalari", "note": "Maşğulot tört savoldan iborat: oftalmologiya fani va uning tibbiyotdagi örni, fanning rivojlaniş tarixi, köruv organining anatomiyasi va közning köriş funksiyalari. Dars yakunida siz közning tuzilişini va beşta asosiy köriş funksiyasini aytib bera olasiz."}, {"title": "Oftalmologiya nima?", "note": "Oftalmologiya sözi yunonça “oftalmos” – köz va “logos” – taʼlimot sözlaridan olingan. Bu fan köruv aʼzosining tuzilişi, faoliyati va kasalliklarini örganadi. Inson taşqi muhit haqidagi maʼlumotlarning sakson–töqson foizini közi orqali oladi. Jahon soğliqni saqlaş taşkilotiga köra, dunyoda ikki milliard ikki yuz million kişida köriş buzilişi mavjud, ularning deyarli yarmida bu holatning oldini oliş mumkin edi."}, {"title": "Oftalmologiyaning boşqa fanlar bilan boğliqligi", "note": "Köplab umumiy kasalliklar közda öz aksini topadi. Gipertoniyada köz tubi tomirlari torayadi, qandli diabetda diabetik retinopatiya va katarakta rivojlanadi. Şuning uçun oftalmolog terapevt, nevropatolog va endokrinolog bilan hamkorlikda işlaydi."}, {"title": "Oftalmologiyada hamşiraning vazifalari", "note": "Hamşira bemorni qabul qiladi va tekşiruvga tayyorlaydi, köriş ötkirligini aniqlaşda iştirok etadi, tomçi dori tomizadi, malham qöyadi va közni yuvadi. Şikastlarda birinçi yordam körsatadi. Köz infeksiyalari oson yuqgani uçun aseptika qoidalariga qatʼiy rioya qiliş şart."}, {"title": "Oftalmologiya tarixi: asosiy bosqiçlar", "note": "Köz kasalliklari haqidagi dastlabki maʼlumotlar qadimgi Misrning Ebers papirusida uçraydi. Hindistonlik tabib Suşruta katarakta operatsiyasini bajargan. Töqqizinçi asrda Hunayn ibn Ishoq “Köz haqida ön maqola” darsligini yozgan. Yangi davrda Kepler tasvir tör pardada hosil bölişini isbotlagan, Daviel kataraktani çiqarib olgan, Gelmgols oftalmoskopni, Snellen esa köriş jadvalini yaratgan."}, {"title": "Abu Ali ibn Sino va Şarq tabobati", "note": "Buyuk vatandoşimiz Abu Ali ibn Sino “Tib qonunlari” asarining uçinçi kitobida köz anatomiyasi va kasalliklarini batafsil bayon qilgan. U közning olti taşqi muskulini, köruv nervi kesişmasini tasvirlagan, traxoma, katarakta va tungi körlik haqida yozgan. Uning asarlari bir neça asr davomida Yevropa universitetlarida darslik bölgan."}, {"title": "XX asr va hozirgi zamon", "note": "Yigirmançi asrda Filatov şox pardani köçirib ötkaziş usulini, Fyodorov esa köz mikroxirurgiyasi va sunʼiy gavhar qöyişni rivojlantirdi. Özbekistonda traxoma ommaviy kasallik sifatida tugatildi, bugun esa kataraktani fakoemulsifikatsiya usulida olib taşlaş va lazer operatsiyalari muvaffaqiyatli bajarilmoqda."}, {"title": "Köruv analizatori", "note": "Köruv analizatori uç qismdan iborat. Periferik qism – köz olmasi va tör parda. Ötkazuvçi yöllar – köruv nervi, köruv nervlari kesişmasi – xiazma, köruv yöllari va taşqi tizzasimon tanalar. Markaziy qism – boş miyaning ensa bölagidagi köriş markazi."}, {"title": "Köz olmasining tuzilişi", "note": "Köz olmasi şarsimon, uning old-orqa öqi örtaça yigirma tört millimetr. Devori uç pardadan iborat: taşqi fibroz parda – şox parda va sklera; örta tomirli parda – rangdor parda, kiprikli tana va xususiy tomirli parda; içki – tör parda. Içida esa köz içi suyuqligi, gavhar va şişasimon tana joylaşgan."}, {"title": "Taşqi – fibroz parda", "note": "Şox parda fibroz pardaning oltidan bir qismini egallaydi. U tiniq, qon tomirlari yöq, lekin nerv tolalariga juda boy, şuning uçun unga tuşgan kiçik yot jism ham kuçli oğriq beradi. Sindiriş kuçi qirq–qirq uç dioptriya. Sklera esa oq, ziç parda bölib, közga şakl beradi va uni himoya qiladi."}, {"title": "Örta – tomirli parda", "note": "Tomirli parda uç qismdan iborat. Rangdor parda közga rang beradi, uning markazidagi qoraçiq fotoapparat diafragmasi kabi közga tuşadigan yoruğlikni boşqaradi. Kiprikli tana köz içi suyuqligini işlab çiqaradi va akkomodatsiyani taʼminlaydi. Xususiy tomirli parda tör pardani oziqlantiradi."}, {"title": "Içki – tör parda", "note": "Tör parda yoruğlikni nerv impulsiga aylantiradi. Unda ikki xil fotoretseptor bor: tayoqçalar qoronğida körişni, kolbaçalar esa kunduzgi va rangli körişni taʼminlaydi. Eng aniq köriş nuqtasi – sariq doğ. Köruv nervi diskida fotoretseptorlar yöq, şuning uçun u kör doğ deb ataladi."}, {"title": "Içki tiniq muhitlar va yordamçi apparat", "note": "Közning içki tiniq muhitlari – köz içi suyuqligi, gavhar va şişasimon tana. Köz içi bosimining normasi Maklakov böyiça ön sakkiz–yigirma olti millimetr simob ustuni. Yordamçi apparatga köz kosasi, qovoqlar, konʼyunktiva, köz yoşi aʼzolari va oltita harakatlantiruvçi muskul kiradi."}, {"title": "Közning 5 ta köriş funksiyasi", "note": "Közning beşta asosiy köriş funksiyasi bor: markaziy köriş, periferik köriş, rang köriş, yoruğlik seziş va binokulyar köriş. Endi ularni qanday tekşirişni körib çiqamiz."}, {"title": "Köriş ötkirligini tekşiriş", "note": "Köriş ötkirligi Sivtsev–Golovin jadvali bilan beş metr masofadan tekşiriladi. Har bir köz alohida tekşiriladi, ikkinçi köz tösiq bilan bosilmasdan yopiladi. Normal köriş ötkirligi birga teng. Agar bemor birinçi qatorni ham körmasa, Snellen formulasi qöllaniladi: köriş ötkirligi bemor öqigan masofani ellikka bölganiga teng."}, {"title": "Köruv maydoni va rang köriş", "note": "Köruv maydoni perimetr asbobida tekşiriladi. Oq rang uçun taşqi çegara töqson daraja, içki çegara ellik beş daraja. Rang köriş esa Rabkin polixromatik jadvallari bilan tekşiriladi. Qizil rangni sezmaslik protanopiya, yaşilni sezmaslik deyteranopiya deb ataladi."}, {"title": "Yoruğlik seziş va binokulyar köriş", "note": "Köz qoronğilikka qirq–oltmiş daqiqada moslaşadi. Bu jarayon buzilsa, gemeralopiya – tovuq körlik yuzaga keladi; uning köp uçraydigan sababi A vitamini yetişmovçiligidir. Binokulyar köriş ikki közdagi tasvirlarning yagona tasvirga qöşilişi bölib, Sokolov sinamasi bilan tekşiriladi."}, {"title": "Xulosa", "note": "Xulosa qilib aytganda, oftalmologiya ijtimoiy ahamiyati juda yuqori fan. Köz olmasi uç parda va uç tiniq muhitdan iborat, közning beşta köriş funksiyasi mavjud. Hamşira köz kasalliklarini erta aniqlaş va profilaktikada muhim örin tutadi. Eʼtiboringiz uçun rahmat! Endi nazorat savollari va testlarga öting."}], "video_len": "7:34"};
